style.css:
@-moz-document domain("youtube.com") {
/* SPONGEBOB x LAVENDER OCEAN | YouTube (Stylus/Stylish) */
:root{--blue:#159eb8;--deep:#075b91;--yellow:#ffdf57;--ink:#173c5b}
html,body{background:#cdb0e8 url("data:image/webp;base64," ) repeat 22px 18px!important;background-size:125px auto!important;background-attachment:fixed!important}
body::before{content:"";position:fixed;inset:0;z-index:-1;pointer-events:none;background:url("data:image/webp;base64,") center/cover no-repeat}
#masthead-container,ytd-masthead{background:linear-gradient(100deg,#087da8,#20b8c8)!important;border-bottom:3px solid var(--yellow)!important}
ytd-guide-renderer,#guide-content,ytd-mini-guide-renderer{background:#108eaf!important}
ytd-guide-entry-renderer:hover,ytd-mini-guide-entry-renderer:hover{background:#ffdf5755!important}
ytd-guide-entry-renderer yt-formatted-string,ytd-guide-entry-renderer #endpoint{color:white!important}
#container.ytd-searchbox,ytd-searchbox #container{background:#fff2a6!important;border:2px solid var(--deep)!important;border-radius:18px 0 0 18px!important}
#search-icon-legacy{background:var(--yellow)!important;border:2px solid var(--deep)!important;border-left:0!important;border-radius:0 18px 18px 0!important}
ytd-rich-grid-renderer,ytd-two-column-browse-results-renderer,ytd-watch-flexy,#primary,#secondary,#below,#comments{background:#e2f6fae8!important;border-radius:14px!important}
ytd-rich-item-renderer:hover,ytd-video-renderer:hover{background:#ffdf5733!important}
ytd-topbar-logo-renderer #logo{width:100px!important;height:40px!important;background:url("data:image/webp;base64,") center/contain no-repeat!important}
ytd-topbar-logo-renderer #logo-icon,ytd-topbar-logo-renderer #country-code{opacity:0!important}
::-webkit-scrollbar{width:10px}::-webkit-scrollbar-track{background:#e6d5f5}::-webkit-scrollbar-thumb{background:var(--blue);border:2px solid #e6d5f5;border-radius:9px}
}
